-- Theory questions for PHY 102. Safe to run twice.
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Electrostatics$q$, $q$State Coulomb's law and write it in mathematical form. State the SI unit of charge.$q$, 5, $q$Coulomb's law states that the force between two point charges is directly proportional to the product of the charges and inversely proportional to the square of the distance between them. In symbols F = k q1 q2 / r^2, where k = 1/(4 pi epsilon-zero), about 9 x 10^9 N m^2 per C^2. The force acts along the line joining the charges and is attractive for unlike charges and repulsive for like charges. The SI unit of charge is the coulomb (C).$q$, $q$[{"t":"Force is proportional to the product of the charges","m":1},{"t":"Force is inversely proportional to the square of the distance","m":1},{"t":"Formula F = k q1 q2 / r^2","m":1},{"t":"Direction: attractive for unlike charges, repulsive for like charges","m":1},{"t":"SI unit of charge is the coulomb","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State Coulomb's law and write it in mathematical form. State the SI unit of charge.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Capacitors$q$, $q$Define capacitance. Derive the effective capacitance of two capacitors C1 and C2 connected in series.$q$, 10, $q$Capacitance is the charge stored per unit potential difference, C = Q/V, measured in farads. In series the same charge Q is on each capacitor. The potential differences are V1 = Q/C1 and V2 = Q/C2. The total potential difference is V = V1 + V2 = Q(1/C1 + 1/C2). The equivalent capacitance is C = Q/V, so 1/C = 1/C1 + 1/C2, which gives C = C1 C2 / (C1 + C2). The effective capacitance is smaller than either capacitor.$q$, $q$[{"t":"Definition C = Q/V, unit farad","m":2},{"t":"States that the charge is the same on each capacitor in series","m":2},{"t":"Writes V1 = Q/C1 and V2 = Q/C2","m":2},{"t":"Total V = V1 + V2","m":2},{"t":"Result 1/C = 1/C1 + 1/C2 (or C1 C2/(C1 + C2))","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define capacitance. Derive the effective capacitance of two capacitors C1 and C2 connected in series.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Current electricity$q$, $q$State Ohm's law. Give two situations in which a conductor does not obey Ohm's law.$q$, 5, $q$Ohm's law states that the current through a conductor is directly proportional to the potential difference across it, provided the temperature and other physical conditions stay constant. In symbols V = IR where R is the resistance. It is not obeyed when the temperature changes, for example a filament lamp, whose resistance rises as it gets hot, so the graph of V against I is curved. It is also not obeyed by semiconductor devices such as diodes, whose current is not proportional to the voltage and which conduct in one direction only.$q$, $q$[{"t":"Current is proportional to potential difference","m":1},{"t":"Condition: constant temperature","m":1},{"t":"Formula V = IR","m":1},{"t":"First non-ohmic example, such as a filament lamp","m":1},{"t":"Second non-ohmic example, such as a diode or other semiconductor","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State Ohm's law. Give two situations in which a conductor does not obey Ohm's law.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Circuits$q$, $q$State Kirchhoff's current law and Kirchhoff's voltage law, and say which conservation law each one depends on.$q$, 5, $q$Kirchhoff's current law says that the sum of the currents entering a junction equals the sum of the currents leaving it, so the algebraic sum of currents at a junction is zero. It depends on conservation of electric charge. Kirchhoff's voltage law says that around any closed loop the algebraic sum of the e.m.f.s equals the algebraic sum of the potential drops (IR terms). It depends on conservation of energy.$q$, $q$[{"t":"Current law: total current into a junction equals total current out","m":1},{"t":"Current law linked to conservation of charge","m":1},{"t":"Voltage law: sum of e.m.f.s equals sum of IR drops around a closed loop","m":1},{"t":"Voltage law linked to conservation of energy","m":1},{"t":"Mentions sign convention or the idea of algebraic sum","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State Kirchhoff's current law and Kirchhoff's voltage law, and say which conservation law each one depends on.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Electromagnetic induction$q$, $q$State Faraday's law and Lenz's law of electromagnetic induction.$q$, 5, $q$Faraday's law states that the induced e.m.f. in a circuit is directly proportional to the rate of change of magnetic flux linked with the circuit, e = -N d(phi)/dt. Lenz's law states that the direction of the induced current is such that it opposes the change in flux that produces it. The minus sign in Faraday's law shows this. Lenz's law is an example of conservation of energy.$q$, $q$[{"t":"Faraday: induced e.m.f. proportional to rate of change of flux linkage","m":2},{"t":"Mathematical form e = -N d(phi)/dt","m":1},{"t":"Lenz: induced current opposes the change that causes it","m":1},{"t":"Link to conservation of energy or meaning of the minus sign","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State Faraday's law and Lenz's law of electromagnetic induction.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Atomic structure$q$, $q$Describe Rutherford's alpha particle scattering experiment and state the conclusions that came from it.$q$, 10, $q$A narrow beam of alpha particles was fired at a very thin gold foil in an evacuated chamber, and the scattered particles were detected on a zinc sulphide screen that flashed when hit. Most alpha particles passed straight through, a few were deflected through large angles, and a very small number were turned back almost the way they came. Conclusions: most of the atom is empty space, since most particles went straight through. The positive charge and most of the mass is concentrated in a very small centre called the nucleus, which explains the large deflections. The nucleus is much smaller than the atom, and electrons move round it outside. This replaced the plum pudding model.$q$, $q$[{"t":"Setup: alpha beam, thin gold foil, detecting screen","m":2},{"t":"Most particles pass straight through","m":2},{"t":"A few deflected through large angles and some reflected back","m":2},{"t":"Conclusion: atom is mostly empty space","m":2},{"t":"Conclusion: small, dense, positively charged nucleus","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Describe Rutherford's alpha particle scattering experiment and state the conclusions that came from it.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Atomic structure$q$, $q$State the postulates of Bohr's model of the hydrogen atom.$q$, 5, $q$Bohr's postulates: (1) The electron moves in certain circular orbits around the nucleus without radiating energy, called stationary states. (2) Only orbits in which the angular momentum of the electron is a whole number multiple of h/2 pi are allowed, so m v r = n h/(2 pi), where n = 1, 2, 3 and so on. (3) The atom emits or absorbs radiation only when an electron jumps from one allowed orbit to another, and the photon energy equals the difference in energy of the two orbits, h f = E_initial - E_final.$q$, $q$[{"t":"Electrons move in stable circular orbits without radiating","m":1},{"t":"Angular momentum is quantised, m v r = n h/(2 pi)","m":2},{"t":"Radiation is emitted or absorbed only in a jump between orbits","m":1},{"t":"Photon energy h f equals the energy difference between the two levels","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State the postulates of Bohr's model of the hydrogen atom.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Electric field$q$, $q$Define electric field intensity. A charge of 2 microcoulombs is placed in a uniform field of 500 N/C. Calculate the force on it.$q$, 5, $q$Electric field intensity at a point is the force per unit positive charge placed at that point, E = F/q. It is a vector quantity measured in newtons per coulomb (N/C) or volts per metre. From E = F/q, F = qE. With q = 2 x 10^-6 C and E = 500 N/C the force is F = 2 x 10^-6 x 500 = 1 x 10^-3 N, which is 1 millinewton. The force is in the direction of the field because the charge is positive.$q$, $q$[{"t":"Definition: force per unit positive charge, E = F/q","m":1},{"t":"States it is a vector with unit N/C","m":1},{"t":"Uses F = qE","m":1},{"t":"Converts 2 microcoulombs to 2 x 10^-6 C","m":1},{"t":"Answer 1 x 10^-3 N","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define electric field intensity. A charge of 2 microcoulombs is placed in a uniform field of 500 N/C. Calculate the force on it.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Electrostatics$q$, $q$State Gauss's law. Use it to write the electric field outside a uniformly charged sphere of total charge Q at a distance r from its centre.$q$, 5, $q$Gauss's law states that the total electric flux through any closed surface equals the net charge enclosed divided by epsilon-zero. In symbols the flux = Q_enclosed/epsilon-zero. For a charged sphere choose a spherical Gaussian surface of radius r outside the sphere. By symmetry the field E is the same size everywhere on this surface and points radially. The flux is E x 4 pi r^2. Setting this equal to Q/epsilon-zero gives E = Q/(4 pi epsilon-zero r^2). This is the field of a point charge Q at the centre.$q$, $q$[{"t":"Statement of Gauss law with enclosed charge and epsilon-zero","m":2},{"t":"Chooses a spherical Gaussian surface and uses symmetry","m":1},{"t":"Flux = E x 4 pi r^2","m":1},{"t":"Result E = Q/(4 pi epsilon-zero r^2)","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State Gauss's law. Use it to write the electric field outside a uniformly charged sphere of total charge Q at a distance r from its centre.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Electric potential$q$, $q$Define electric potential difference. Calculate the work done in moving a charge of 2 microcoulombs through a potential difference of 12 volts.$q$, 5, $q$The potential difference between two points is the work done per unit charge in moving a positive charge from one point to the other, V = W/q. Its unit is the volt, which is one joule per coulomb. From V = W/q, W = qV. With q = 2 x 10^-6 C and V = 12 V, W = 2 x 10^-6 x 12 = 2.4 x 10^-5 J.$q$, $q$[{"t":"Definition: work per unit charge","m":1},{"t":"Unit: volt = joule per coulomb","m":1},{"t":"Uses W = qV","m":1},{"t":"Answer 2.4 x 10^-5 J","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define electric potential difference. Calculate the work done in moving a charge of 2 microcoulombs through a potential difference of 12 volts.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Capacitors$q$, $q$Derive the effective capacitance of two capacitors in parallel. A 10 microfarad capacitor is charged to 100 volts. Calculate the energy stored.$q$, 5, $q$In parallel each capacitor has the same potential difference V. The charges are Q1 = C1 V and Q2 = C2 V. The total charge is Q = Q1 + Q2 = (C1 + C2)V. So the effective capacitance C = Q/V = C1 + C2. The energy stored in a capacitor is U = (1/2) C V^2. With C = 10 x 10^-6 F and V = 100 V, U = 0.5 x 10 x 10^-6 x 10^4 = 0.05 J.$q$, $q$[{"t":"Same V across each capacitor in parallel","m":1},{"t":"Total charge Q = Q1 + Q2","m":1},{"t":"C = C1 + C2","m":1},{"t":"Energy formula U = (1/2) C V^2","m":1},{"t":"Answer 0.05 J","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Derive the effective capacitance of two capacitors in parallel. A 10 microfarad capacitor is charged to 100 volts. Calculate the energy stored.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Current electricity$q$, $q$Define resistivity. Calculate the resistance of a copper wire 2 m long with cross-sectional area 1 x 10^-6 m^2. (Resistivity of copper = 1.7 x 10^-8 ohm metre.)$q$, 5, $q$Resistivity is a property of a material, defined by R = rho L/A, where R is the resistance, L the length and A the cross-sectional area. It is measured in ohm metres. Substituting, R = (1.7 x 10^-8 x 2)/(1 x 10^-6) = 3.4 x 10^-8/10^-6 = 0.034 ohm.$q$, $q$[{"t":"Definition through R = rho L/A","m":1},{"t":"Unit ohm metre","m":1},{"t":"Correct substitution","m":1},{"t":"Answer 0.034 ohm","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define resistivity. Calculate the resistance of a copper wire 2 m long with cross-sectional area 1 x 10^-6 m^2. (Resistivity of copper = 1.7 x 10^-8 ohm metre.)$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Circuits$q$, $q$A 3 ohm and a 6 ohm resistor are connected in parallel and this combination is connected in series with a 4 ohm resistor across a 12 V battery. Find the total resistance and the current from the battery.$q$, 5, $q$For the parallel pair, 1/R = 1/3 + 1/6 = 2/6 + 1/6 = 3/6, so R = 2 ohm. This is in series with 4 ohm, so the total resistance is 2 + 4 = 6 ohm. By Ohm's law the current is I = V/R = 12/6 = 2 A.$q$, $q$[{"t":"Parallel formula used correctly","m":1},{"t":"Parallel pair = 2 ohm","m":1},{"t":"Total resistance 6 ohm","m":1},{"t":"Uses I = V/R","m":1},{"t":"Current 2 A","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$A 3 ohm and a 6 ohm resistor are connected in parallel and this combination is connected in series with a 4 ohm resistor across a 12 V battery. Find the total resistance and the current from the battery.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Electrical power$q$, $q$State three formulae for electrical power. A 60 W bulb is used for 5 hours. Find the energy used in kilowatt-hours.$q$, 5, $q$Electrical power P = IV = I^2 R = V^2/R, where I is the current, V the potential difference and R the resistance. Energy in kilowatt-hours is the power in kilowatts multiplied by the time in hours. 60 W = 0.06 kW. Energy = 0.06 x 5 = 0.3 kWh.$q$, $q$[{"t":"Any three correct power formulae","m":2},{"t":"Converts 60 W to 0.06 kW","m":1},{"t":"Energy = power x time","m":1},{"t":"Answer 0.3 kWh","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State three formulae for electrical power. A 60 W bulb is used for 5 hours. Find the energy used in kilowatt-hours.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Current electricity$q$, $q$Explain what is meant by the internal resistance of a cell. A battery of e.m.f. 12 V and internal resistance 0.5 ohm supplies a current of 4 A. Find the terminal potential difference.$q$, 5, $q$The internal resistance is the resistance to the flow of current inside the cell itself. Some of the e.m.f. is used to drive current through it, so the terminal voltage is less than the e.m.f. when a current flows. The relation is E = V + Ir, so V = E - Ir. With E = 12 V, I = 4 A and r = 0.5 ohm, the lost voltage is Ir = 2 V. So V = 12 - 2 = 10 V.$q$, $q$[{"t":"Meaning of internal resistance","m":1},{"t":"Relation E = V + Ir","m":1},{"t":"Lost volts Ir = 2 V","m":1},{"t":"Terminal voltage 10 V","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Explain what is meant by the internal resistance of a cell. A battery of e.m.f. 12 V and internal resistance 0.5 ohm supplies a current of 4 A. Find the terminal potential difference.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Magnetism$q$, $q$Write the expression for the magnetic force on a charge moving in a magnetic field. An electron moves at 2 x 10^6 m/s perpendicular to a magnetic field of 0.5 T. Find the force on it. (Charge of an electron = 1.6 x 10^-19 C.)$q$, 5, $q$The magnetic force on a charge q moving with velocity v in a field B is F = q v B sin(theta), where theta is the angle between v and B. The force is perpendicular to both v and B, so it changes the direction of motion but does no work. For perpendicular motion, sin(theta) = 1. F = 1.6 x 10^-19 x 2 x 10^6 x 0.5 = 1.6 x 10^-13 N.$q$, $q$[{"t":"Expression F = q v B sin(theta)","m":1},{"t":"Force perpendicular to v and B","m":1},{"t":"Sin(theta) = 1 for perpendicular motion","m":1},{"t":"Answer 1.6 x 10^-13 N","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Write the expression for the magnetic force on a charge moving in a magnetic field. An electron moves at 2 x 10^6 m/s perpendicular to a magnetic field of 0.5 T. Find the force on it. (Charge of an electron = 1.6 x 10^-19 C.)$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Magnetism$q$, $q$A straight wire 0.3 m long carries a current of 5 A in a magnetic field of 0.4 T at right angles to the wire. Find the force on the wire. State the rule used to find its direction.$q$, 5, $q$The force on a current-carrying conductor in a magnetic field is F = B I L sin(theta). At right angles sin(theta) = 1. So F = 0.4 x 5 x 0.3 = 0.6 N. The direction is given by Fleming's left-hand rule: with the thumb, first finger and second finger of the left hand held at right angles, the first finger points along the field, the second finger along the current and the thumb shows the direction of the force (motion).$q$, $q$[{"t":"Formula F = B I L","m":1},{"t":"Substitutes correctly","m":1},{"t":"Answer 0.6 N","m":1},{"t":"States Fleming left-hand rule with the three fingers","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$A straight wire 0.3 m long carries a current of 5 A in a magnetic field of 0.4 T at right angles to the wire. Find the force on the wire. State the rule used to find its direction.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Magnetism$q$, $q$Write the expression for the magnetic field at a distance r from a long straight wire carrying current I. Calculate the field 5 cm from a wire carrying 10 A. (mu-zero = 4 pi x 10^-7 T m/A.)$q$, 5, $q$The magnetic field at distance r from a long straight wire is B = mu-zero I/(2 pi r). Here I = 10 A and r = 0.05 m. B = (4 pi x 10^-7 x 10)/(2 pi x 0.05) = (2 x 10^-7 x 10)/0.05 = 2 x 10^-6/0.05 = 4 x 10^-5 T. The field lines are circles around the wire, in the direction given by the right-hand grip rule.$q$, $q$[{"t":"Expression B = mu-zero I/(2 pi r)","m":2},{"t":"Converts 5 cm to 0.05 m","m":1},{"t":"Answer 4 x 10^-5 T","m":1},{"t":"Field lines are circles, right-hand grip rule","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Write the expression for the magnetic field at a distance r from a long straight wire carrying current I. Calculate the field 5 cm from a wire carrying 10 A. (mu-zero = 4 pi x 10^-7 T m/A.)$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Alternating current$q$, $q$Explain the working principle of a transformer. A transformer has 1000 turns on its primary coil and is connected to 240 V. How many turns must the secondary coil have to give 12 V?$q$, 5, $q$A transformer works by mutual induction. An alternating current in the primary coil produces a changing magnetic flux in the iron core. This flux links the secondary coil and induces an alternating e.m.f. in it. For an ideal transformer Vs/Vp = Ns/Np. So Ns = Np x Vs/Vp = 1000 x 12/240 = 50 turns. This is a step-down transformer because the secondary voltage is lower.$q$, $q$[{"t":"Mutual induction and changing flux in the core","m":2},{"t":"Relation Vs/Vp = Ns/Np","m":1},{"t":"Ns = 50 turns","m":1},{"t":"Identifies it as step-down","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Explain the working principle of a transformer. A transformer has 1000 turns on its primary coil and is connected to 240 V. How many turns must the secondary coil have to give 12 V?$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Alternating current$q$, $q$Define the root-mean-square (r.m.s.) value of an alternating voltage. A mains supply has a peak voltage of 311 V. Find its r.m.s. value.$q$, 5, $q$The r.m.s. value of an alternating voltage is the value of the steady d.c. voltage that would dissipate the same power in a resistor. For a sinusoidal supply V_rms = V_0/sqrt(2). With V_0 = 311 V, V_rms = 311/1.414 = 220 V (approximately).$q$, $q$[{"t":"Definition through equal power in a resistor","m":2},{"t":"Formula V_rms = V_0/sqrt(2)","m":1},{"t":"Answer 220 V","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define the root-mean-square (r.m.s.) value of an alternating voltage. A mains supply has a peak voltage of 311 V. Find its r.m.s. value.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Photoelectric effect$q$, $q$State Einstein's photoelectric equation and explain the term work function. Light with photons of energy 3.0 eV falls on a metal of work function 2.0 eV. Find the maximum kinetic energy of the emitted electrons.$q$, 5, $q$Einstein's equation is h f = phi + KE_max, where h f is the photon energy, phi the work function and KE_max the maximum kinetic energy of the emitted electron. The work function is the minimum energy needed to remove an electron from the surface of the metal. KE_max = 3.0 - 2.0 = 1.0 eV. Electrons are only emitted if the photon energy is at least equal to the work function, which defines a threshold frequency f_0 = phi/h.$q$, $q$[{"t":"Equation h f = phi + KE_max","m":1},{"t":"Meaning of work function","m":1},{"t":"KE_max = 1.0 eV","m":2},{"t":"Threshold frequency idea","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State Einstein's photoelectric equation and explain the term work function. Light with photons of energy 3.0 eV falls on a metal of work function 2.0 eV. Find the maximum kinetic energy of the emitted electrons.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Radioactivity$q$, $q$State two properties of each of alpha, beta and gamma radiation. A sample contains 80 g of a radioactive substance of half-life 4 days. Find the mass left after 12 days.$q$, 5, $q$Alpha particles are helium nuclei, strongly ionising and stopped by paper. Beta particles are fast electrons, moderately ionising and stopped by a few millimetres of aluminium. Gamma rays are electromagnetic waves, weakly ionising and need thick lead or concrete to reduce them. The half-life is the time for half the nuclei to decay. 12 days is 12/4 = 3 half-lives. The mass goes 80, 40, 20, 10. So 10 g remain.$q$, $q$[{"t":"Two correct properties of alpha","m":1},{"t":"Two correct properties of beta","m":1},{"t":"Two correct properties of gamma","m":1},{"t":"Number of half-lives = 3","m":1},{"t":"Mass left 10 g","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State two properties of each of alpha, beta and gamma radiation. A sample contains 80 g of a radioactive substance of half-life 4 days. Find the mass left after 12 days.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$PHY 102$q$, $q$Electricity, Magnetism and Atomic Physics$q$, $q$Atomic structure$q$, $q$The energy of the nth level of the hydrogen atom is E_n = -13.6/n^2 electronvolts. Calculate the energy of the photon emitted when the electron falls from n = 3 to n = 2.$q$, 5, $q$E_3 = -13.6/9 = -1.51 eV and E_2 = -13.6/4 = -3.40 eV. The photon energy equals the difference between the two levels: E = E_3 - E_2 = -1.51 - (-3.40) = 1.89 eV. This is visible red light at a wavelength of about 656 nm.$q$, $q$[{"t":"E_3 = -1.51 eV","m":1},{"t":"E_2 = -3.40 eV","m":1},{"t":"Photon energy is the difference of the levels","m":1},{"t":"Answer 1.89 eV","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$The energy of the nth level of the hydrogen atom is E_n = -13.6/n^2 electronvolts. Calculate the energy of the photon emitted when the electron falls from n = 3 to n = 2.$q$);
select course_code, count(*) as questions from public.theory_questions group by course_code order by course_code;
